DECLARE
  v_total NUMBER(10,2);
BEGIN
  SELECT SUM(list_price) INTO v_total
  FROM products WHERE product_line = 'R';
  IF v_total > 100000 THEN
    DBMS_OUTPUT.PUT_LINE('High-value');
  END IF;
END;

CREATE PROCEDURE CheckProductLine()
BEGIN
  DECLARE total DECIMAL(10,2);
  SELECT SUM(list_price) INTO total
  FROM products WHERE product_line = 'R';
  IF total > 100000 THEN
    SELECT 'High-value product line';
  END IF;
END

DO $$
DECLARE
  total NUMERIC(10,2);
BEGIN
  SELECT SUM(list_price) INTO total
